var a=`1063-kuih-seri-muka`;var t=`world-1063`;var n=`MY`;var r=`southeast-asia`;var o=8;var s=369;var u={en:`Kuih Seri Muka`,ua:`Куї сері мука`};var l={en:`Kuih Seri Muka is a dish from Malaysia prepared with glutinous rice, coconut milk, chicken egg, pandan leaves. This is a home-scale version with measured ingredients in the individual steps where they are used.`,ua:`Куї сері мука, страва кухні країни Малайзія, яку готують із таких продуктів: клейкий рис, кокосове молоко, куряче яйце, листя пандану. Кількості в домашньому рецепті прив’язані до окремих етапів приготування.`};var d=[{en:`Soak the measured rice or noodles in clean cool water for about 220 minutes, then drain and proceed to the specified cooking step.`,ua:`Замочіть зазначені рис або локшину в чистій прохолодній воді близько 220 хвилин, злийте і переходьте до подальшого готування.`,t:[`rice-soaking`],m:220,i:[[`glutinous-rice`,360,`g`],[`water`,850,`ml`]]},{en:`Steam the prepared ingredients in a covered steamer for about 25 minutes, until fully set or cooked; use food-safe leaves and ensure any protein reaches a safe temperature.`,ua:`Готуйте підготовлені продукти у пароварці під кришкою близько 25 хвилин до повної готовності; використовуйте харчове листя й перевіряйте температуру білкових продуктів.`,t:[`steaming`],m:25,i:[[`coconut-milk`,220,`ml`],[`table-salt`,3,`g`]]},{en:`Combine the listed ingredients in a bowl until evenly mixed; avoid overworking delicate components.`,ua:`З’єднайте зазначені складники в мисці до однорідності; не перемішуйте ніжні компоненти надто довго.`,t:[`mixing`],m:9,i:[[`chicken-egg`,4,`pcs`],[`coconut-milk`,250,`ml`],[`palm-sugar`,145,`g`],[`pandan-leaves`,3,`leaf`]]},{en:`Pour the strained pandan-coconut egg custard over the already steamed sticky-rice layer and steam gently until fully set.`,ua:`Вилийте проціджений панданно-кокосовий яєчний крем поверх уже пропареного липкого рису й обережно пропарте до повного застигання.`,t:[`steaming`],m:25,i:[]},{en:`Refrigerate the prepared mixture for about 90 minutes, cooling perishable foods promptly and never holding cooked rice warm at room temperature.`,ua:`Охолоджуйте підготовлену масу в холодильнику близько 90 хвилин; швидко охолоджуйте швидкопсувні продукти й не тримайте готовий рис у теплі при кімнатній температурі.`,t:[`rapid-chilling`],m:90,i:[]}];var m={slug:a,id:t,country:`MY`,region:r,servings:8,minutes:369,title:u,text:l,steps:d};export{n as country,m as default,t as id,s as minutes,r as region,o as servings,a as slug,d as steps,l as text,u as title};